CREATE TABLE IF NOT EXISTS gg_shops(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE,phone TEXT,location TEXT,status TEXT DEFAULT 'active',plan TEXT DEFAULT 'FREE',expiry INTEGER);
CREATE TABLE IF NOT EXISTS gg_users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL,shop TEXT,force INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS gg_sessions(id TEXT PRIMARY KEY,uid TEXT NOT NULL,csrf TEXT NOT NULL,expiry INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS gg_data(shop TEXT PRIMARY KEY,version INTEGER DEFAULT 0,data TEXT);
CREATE TABLE IF NOT EXISTS gg_public(id TEXT PRIMARY KEY,shop TEXT NOT NULL,name TEXT NOT NULL,price INTEGER NOT NULL,category TEXT,type TEXT,description TEXT,image TEXT,stock INTEGER);
CREATE TABLE IF NOT EXISTS gg_requests(id TEXT PRIMARY KEY,shop TEXT,plan TEXT,reference TEXT UNIQUE,status TEXT DEFAULT 'pending',created INTEGER);
CREATE TABLE IF NOT EXISTS gg_audit(id TEXT PRIMARY KEY,uid TEXT,shop TEXT,action TEXT,created INTEGER);
CREATE TABLE IF NOT EXISTS gg_limits(key TEXT PRIMARY KEY,n INTEGER,until INTEGER);
CREATE INDEX IF NOT EXISTS gg_public_shop ON gg_public(shop);
CREATE INDEX IF NOT EXISTS gg_sessions_uid ON gg_sessions(uid);
